param([string]$BenchmarkRepo="D:\Dev\LotSizingDataModel.Benchmarks")
Set-StrictMode -Version Latest;$ErrorActionPreference="Stop";$g=Join-Path $BenchmarkRepo "catalog\global";$registry=@(Import-Csv -LiteralPath (Join-Path $g "GLOBAL-BENCHMARK-REGISTRY-v0.21.0.csv"));$trust=@(Import-Csv -LiteralPath (Join-Path $g "GLOBAL-NORMALIZED-TRUST-v0.21.0.csv"));if($registry.Count -ne 7905 -or $trust.Count -ne 7905){throw "7905-row invariant failed."};$counts=@{};foreach($x in $registry){if(-not $counts.ContainsKey($x.family)){$counts[$x.family]=0};$counts[$x.family]++};$expected=@{CATTRYSSE1990=120;DJ2000=176;STADTLER2003=2100;SUERIE_CLSPL=1291;TD1996=3450;TRIGEIRO1989=751;EM1987=17};foreach($k in $expected.Keys){if($counts[$k] -ne $expected[$k]){throw "Family invariant failed: $k"}};if(@($registry|Group-Object global_instance_id|Where-Object Count -gt 1).Count -ne 0){throw "Global IDs not unique."};if(@($registry|Group-Object fingerprint|Where-Object Count -gt 1).Count -ne 0){throw "Fingerprint duplicates."};if(@($trust|Where-Object family -eq "EM1987"|Where-Object normalized_trust_status -ne "NO_REFERENCE_KNOWN").Count -ne 0){throw "Unsafe EM trust promotion."};if(@(Import-Csv -LiteralPath (Join-Path $g "MISSING-FAMILY-ACQUISITION-v0.21.0.csv")).Count -ne 5){throw "Missing-family manifest invariant failed."};Write-Host "GLOBAL_EM1987_V0.21.0_VALID";Write-Host "ROWS|7905";Write-Host "EM1987|17";Write-Host "HISTORICAL_BASELINE|7888";Write-Host "DUPLICATE_CLUSTERS|0";Write-Host "TRUST_PROMOTIONS|0"
